SELECT u.name, o.amount, ROW_NUMBER() OVER (PARTITION BY u.city ORDER BY o.amount DESC) AS rn, RANK() OVER (PARTITION BY u.city ORDER BY o.amount DESC) AS rnk, DENSE_RANK() OVER (PARTITION BY u.city ORDER BY o.amount DESC) AS drnk, SUM(o.amount) OVER (PARTITION BY u.city ORDER BY o.amount DESC) AS city_total_amount FROM users u JOIN orders o ON u.id = o.user_id ORDER BY u.city, rn LIMIT 15;
